import{_ as o,r as a,o as p,c as i,e as s,a as c,s as l}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Resizer - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Introduction","slug":"introduction","link":"#introduction","children":[]},{"level":2,"title":"Resize a File on Disk","slug":"resize-a-file-on-disk","link":"#resize-a-file-on-disk","children":[{"level":3,"title":"Resize Parameters","slug":"resize-parameters","link":"#resize-parameters","children":[]},{"level":3,"title":"Available Modes","slug":"available-modes","link":"#available-modes","children":[]}]},{"level":2,"title":"Resize a File to Browser","slug":"resize-a-file-to-browser","link":"#resize-a-file-to-browser","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/extend/services/resizer.md","filePath":"3.x/extend/services/resizer.md"}'),r={name:"3.x/extend/services/resizer.md"};function d(u,e,h,k,g,m){const t=a("pre-heading"),n=a("post-heading");return p(),i("div",null,[s(t),e[0]||(e[0]=c("h1",null,"Resizer",-1)),s(n),e[1]||(e[1]=l(`<h2 id="introduction"><a href="#introduction" class="header-anchor">#</a> Introduction</h2><p>October CMS ships with an image resizer that lets you change the shape and size of supported images.</p><h2 id="resize-a-file-on-disk"><a href="#resize-a-file-on-disk" class="header-anchor">#</a> Resize a File on Disk</h2><p>To resize an image, use the <code>open</code> method on the <code>Resizer</code> facade to target a file path.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span> <span class="token operator">=</span> <span class="token class-name static-context">Resizer</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/image.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also pass an uploaded file from the <a href="./request-input.html">page request input</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span> <span class="token operator">=</span> <span class="token class-name static-context">Resizer</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;field_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To resize the image, call the <code>resize</code> method on the object to perform the resize. The first argument is the image width, the second argument is the image height and the third argument is an array of resize parameters.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;mode&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;crop&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The width and height arguments are also optional, for example, to use the existing width and only adjust the height, pass the second argument as <code>null</code>. This value is then calculated using original image ratio (automatic proportional scaling) based on the <code>mode</code> option.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token constant">null</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Finally, use the <code>save</code> method to save the resized image to a new location.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/new/file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="resize-parameters"><a href="#resize-parameters" class="header-anchor">#</a> Resize Parameters</h3><p>The following elements are supported in the options array are supported:</p><div class="table"><table tabindex="0"><thead><tr><th>Key</th><th>Description</th><th>Default</th><th>Options</th></tr></thead><tbody><tr><td><code>mode</code></td><td>How the image should be fitted to dimensions</td><td><code>auto</code></td><td><code>exact</code>, <code>portrait</code>, <code>landscape</code>, <code>auto</code>, <code>fit</code>, or <code>crop</code></td></tr><tr><td><code>offset</code></td><td>Offset the crop of the resized image</td><td><code>[0,0]</code></td><td>[left, top]</td></tr><tr><td><code>quality</code></td><td>Quality of the resized image</td><td><code>90</code></td><td><code>0-100</code></td></tr><tr><td><code>sharpen</code></td><td>Amount to sharpen the image</td><td><code>0</code></td><td><code>0-100</code></td></tr></tbody></table></div><h3 id="available-modes"><a href="#available-modes" class="header-anchor">#</a> Available Modes</h3><p>The <code>mode</code> option allows you to specify how the image should be resized. The available modes are as follows:</p><div class="table"><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><code>auto</code></td><td>Automatically choose between <code>portrait</code> and <code>landscape</code> based on the image&#39;s orientation</td></tr><tr><td><code>exact</code></td><td>Resize to the exact dimensions given, without preserving aspect ratio</td></tr><tr><td><code>portrait</code></td><td>Resize to the given height and adapt the width to preserve aspect ratio</td></tr><tr><td><code>landscape</code></td><td>Resize to the given width and adapt the height to preserve aspect ratio</td></tr><tr><td><code>crop</code></td><td>Crop to the given dimensions after fitting as much of the image as possible inside those</td></tr><tr><td><code>fit</code></td><td>Fit the image inside the given maximal dimensions, keeping the aspect ratio</td></tr></tbody></table></div><h2 id="resize-a-file-to-browser"><a href="#resize-a-file-to-browser" class="header-anchor">#</a> Resize a File to Browser</h2><p>The <code>System\\Classes\\ResizeImages</code> class can be used to resize an image and serve it via a URL:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$url</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token variable">$image</span><span class="token punctuation">,</span> <span class="token variable">$width</span><span class="token punctuation">,</span> <span class="token variable">$height</span><span class="token punctuation">,</span> <span class="token variable">$options</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If you are resizing a media library item, you should resolve the media path using the <code>Media\\Classes\\MediaLibrary</code> class and <code>url</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Media<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>MediaLibrary</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;relative/path/to/asset.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$url</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token variable">$image</span><span class="token punctuation">,</span> <span class="token variable">$width</span><span class="token punctuation">,</span> <span class="token variable">$height</span><span class="token punctuation">,</span> <span class="token variable">$options</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>There is also a <code>|resize</code> <a href="./../../markup/filter/resize.html">markup filter</a> that can be used for resizing images in your themes.</p></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../markup/filter/resize.html">Resize Filter</a></li><li><a href="./../../markup/filter/media.html">Media Filter</a></li></ul></div>`,27))])}const b=o(r,[["render",d]]);export{v as __pageData,b as default};
